import {createEngine,BASE_MULTIPLIERS,FREE_MULTIPLIERS,DEFAULT_PAYTABLE,MATH_VERSION,BET_UNIT,maxBet} from './engine.js?v=reward-sync-v1';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const reviewMode=new URLSearchParams(location.search).has('review');const sessionStorageAdapter=reviewMode?{getItem:()=>null,setItem:()=>{}}:localStorage;const engine=createEngine(),journal=createJournal(sessionStorageAdapter),saved=journal.read();
const legacy=(()=>{try{return reviewMode?{}:JSON.parse(localStorage.getItem('gala-carrot-v1'))||{}}catch{return{}}})();
const initial=['J','K','Q','A','S','H','S','D','C','J','Q','D','K','H','D','C','J','H','A','K'].map((symbol,i)=>({symbol,gold:[1,12,18].includes(i)}));
let balance=saved?.balance??(Number.isFinite(legacy.balance)?legacy.balance:2000),bet=saved?.bet??clampBet((saved?.balance??legacy.balance??2000)*.01,saved?.balance??legacy.balance??2000),board=saved?.board??initial,busy=false,speed=0,soundOn=false,audio,free=saved?.free??0,freeTotal=saved?.freeTotal??0,lastWin=saved?.lastWin??0,auto=null,stopRequested=false,featureResolver=null,isDemo=false,activeRound=saved?.active??null,recoveryPrompt=false;
const sessionTotal=createSessionTotal(reviewMode?sessionStorageAdapter:sessionStorage,balance);
const fmt=compactMoney,suits={S:'♠',H:'♥',C:'♣',D:'♦'},durations=[1,.5],playback=createPlaybackClock(),effects=createEffects({clock:playback,getSpeed:()=>speed});
const wait=ms=>playback.wait(ms),effect=(id,detail={})=>effects.play('ANIM-'+String(id).padStart(2,'0'),detail);
const scenes=createCarrotScenes(effects);
const pauseReasons=new Set();
function msg(t){$('#message').textContent=t}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function tone(freq=600,d=.08){if(!soundOn)return;try{audio??=new AudioContext();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.start();o.stop(audio.currentTime+d)}catch{}}
function save(){if(isDemo)return;journal.write({balance,bet,board,free,freeTotal,lastWin,active:activeRound})}
function cardHTML(c){const special=['CARROT','ANGEL','DEVIL'].includes(c.symbol),path=c.symbol==='CARROT'?'carrot-bonus.png':c.symbol==='ANGEL'?'wild-angel-fitted.svg':c.symbol==='DEVIL'?'wild-devil-fitted.svg':`card-${c.gold?'gold':'normal'}-${c.symbol}.png`;return `<div class="card ${special?'special':''} ${c.gold?'gold':''}"><img class="art-card" src="assets/art/${path}" alt="${c.symbol}">${c.gold&&!special?'<img class="gold-frame-art" src="assets/art/card-gold-overlay.png" alt="" aria-hidden="true">':''}</div>`}
function render(){const nodes=$$('#board .cell');board.forEach((c,i)=>{let n=nodes[i];if(!n){n=document.createElement('div');$('#board').append(n)}n.className='cell '+(c.symbol==='CARROT'?'carrot':['ANGEL','DEVIL'].includes(c.symbol)?'wild':'');n.dataset.index=i;n.setAttribute('aria-label',`${Math.floor(i/5)+1}行${i%5+1}列 ${c.symbol}`);const key=c.symbol+':'+Number(c.gold);if(n.dataset.face!==key){n.innerHTML=cardHTML(c);n.dataset.face=key}});update()}
function fitAmounts(){for(const[id,value]of[['balance',balance],['bet',bet],['win',lastWin]]){const el=$('#'+id);el.title=exactMoney(value);el.setAttribute('aria-label',exactMoney(value)+' 蘿蔔');const field=el.closest('.money-field');if(field){delete field.dataset.stacked;const row=el.closest('.amount-value');if(row&&row.scrollWidth>field.clientWidth-2)field.dataset.stacked='true'}}}
function update(){playback.setScale(durations[speed]);effects.setPlaybackRate(speed);document.documentElement.style.setProperty('--motion-scale',durations[speed]);$('#speed').dataset.speed=String(speed);$('#sound').setAttribute('aria-pressed',String(soundOn));if(!busy&&!free&&!activeRound)bet=clampBet(bet,balance);const net=sessionTotal.net(balance);$('#sessionValue').textContent=(net>0?'＋':net<0?'−':'')+fmt(Math.abs(net));$('#sessionLabel').textContent=net>0?'本次淨贏':net<0?'本次淨輸':'本次淨輸贏';$('#sessionTotal').dataset.sign=net>0?'positive':net<0?'negative':'neutral';$('#sessionTotal').title=exactMoney(net)+' 蘿蔔';$('#balance').textContent=fmt(balance);$('#bet').textContent=fmt(bet);$('#win').textContent=fmt(lastWin);fitAmounts();$('#spin').disabled=busy||free>0||!!activeRound||bet<BET_UNIT||bet>maxBet(balance);for(const id of ['plus','minus','betEntry'])$('#'+id).disabled=busy||free>0||!!activeRound;$('#auto').classList.toggle('on',!!auto);$('#auto small').textContent=auto?String(auto.left):'AUTO';$('#auto').setAttribute('aria-label',auto?'停止自動遊戲':'自動遊戲設定');$('#speed small').textContent=['正常','2×'][speed];$('#speed').setAttribute('aria-label','切換速度，目前'+['正常','快速'][speed]);$('#freePill').hidden=!(free>0||(busy&&activeRound?.plan.isFree));$('#freePill').textContent=free?`免費 ${free} 次`:'最後免費局';$('#modeLabel').textContent=free?'THE CARROT CELEBRATION':'LET THE CARROTS FALL';$('#freeLabel').textContent=free?'FREE GAME':'1024 WAYS';$('.game').classList.toggle('free-mode',free>0||(busy&&!!activeRound?.plan.isFree))}
function setMultiplier(step,isFree){scenes.set(Math.min(step,3),isFree);const vals=isFree?FREE_MULTIPLIERS:BASE_MULTIPLIERS;$('#multipliers').innerHTML=vals.map((v,i)=>`<span class="${i===Math.min(step,3)?'active':''}">×${v}</span>`).join('')}
function openModal(html,animation=46){waterfall?.stop();waterfall=null;modalVersion++;closing=false;$('#modal').classList.remove('auto-modal','reward-modal','feature-modal','retrigger','is-mega','is-total');$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();if(animation)effect(animation,{target:$('#modalContent')})}
let modalVersion=0,closing=false,waterfall=null;
async function close(){if(recoveryPrompt){resumeRecovery();return}if(closing)return;closing=true;const version=modalVersion,resolver=featureResolver,id=$('#modal').classList.contains('auto-modal')?42:46;effect(id,{target:$('#modalContent'),closing:true});await wait(effects.durationFor(id));if(version!==modalVersion){closing=false;return}waterfall?.stop();waterfall=null;$('#modal').close();if(featureResolver===resolver){featureResolver=null;resolver?.()}closing=false}
$('#closeModal').onclick=close;$('#modal').addEventListener('cancel',e=>{e.preventDefault();close()});
function confirmation(id){return new Promise(resolve=>{featureResolver=resolve;$('#'+id).onclick=()=>{effect(40,{target:$('#'+id)});if(effects.finishCounters())return;close()}})}
function idle(){effects.startIdle()}
async function feature(n,extra=false){
 openModal(`<div class="free-feature-art"><img id="featureHero" src="assets/art/v5/free-carrot-hero.svg" alt="金色蘿蔔慶典"></div><h2 class="free-feature-title">${extra?'MORE CARROTS!':'FREE CARROT SPIN'}</h2><div class="free-award-count">${extra?'＋':''}${n}<small>FREE SPINS</small></div><p class="free-feature-multipliers">×2　×4　×6　×10</p><div class="btn-row"><button class="btn primary" id="featureGo">${extra?'繼續免費遊戲':'開始免費遊戲'}</button></div>`,0);
 $('#modal').classList.add('feature-modal');if(extra)$('#modal').classList.add('retrigger');effect(32,{target:$('#featureHero')});await confirmation('featureGo');
}
async function prize(title,amount,id,animation){
 const mega=title==='MEGA WIN';openModal(`<img class="reward-pile" src="assets/art/v5/carrot-pile.svg" alt=""><div class="feature-title">${title}</div><p class="reward-amount"><img class="currency-inline" src="assets/carrot.png" alt="蘿蔔"> ${fmt(amount)}</p><div class="btn-row"><button class="btn primary" id="${id}">收下獎勵</button></div>`,0);
 $('#modal').classList.add('reward-modal');if(mega)$('#modal').classList.add('is-mega');if(title==='TOTAL WIN')$('#modal').classList.add('is-total');waterfall=effects.startWaterfall($('#modal'),{mega});effect(animation,{amount,from:0,target:$('.reward-amount')});await confirmation(id);
}
function applyState(state){balance=state.balance;free=state.free;freeTotal=state.freeTotal}
async function runRecord(record,{recovering=false}={}){
 busy=true;isDemo=!!record.demo;activeRound=record.demo?null:record;effects.stopIdle();const plan=record.plan,roundBet=plan.bet;lastWin=0;setMultiplier(0,plan.isFree);update();
 try{
  msg(plan.isFree?'免費遊戲進行中…':'正在發牌…');await effects.ready;
  if(recovering)effect(48,{resuming:true});
  if(!record.credited){
   effect(2);effect(3,{indices:board.map((_,i)=>i)});await wait(260);
   board=structuredClone(plan.initialBoard);render();
   const covers=board.map((_,index)=>{const img=document.createElement('img');img.className='reveal-cover';img.src='assets/back.png';img.alt='待揭牌';$$('#board .cell')[index].querySelector('.card').append(img);return img});
   $$('#board .cell').forEach(el=>el.classList.add('feed-waiting'));const revealedCarrots=[],feeds=[];effect(4);
   for(let col=0;col<5;col++){
    const indices=[col,col+5,col+10,col+15],anticipating=revealedCarrots.length===2;
    if(anticipating){msg('再一個 CARROT，開啟免費遊戲');effect(27,{indices:revealedCarrots});effect(28,{indices});await wait(650)}
    indices.forEach(index=>covers[index].remove());const feed=effect(5,{indices,slow:anticipating});feeds.push(feed.finished);
    const landed=indices.filter(i=>board[i].symbol==='CARROT');if(anticipating||landed.length)await feed.finished;else await wait(70);if(landed.length){const before=revealedCarrots.length;revealedCarrots.push(...landed);effect(25,{indices:landed});if(before<3&&revealedCarrots.length>=3){effect(30,{indices:[revealedCarrots[2]]});await wait(400)}}
    if(anticipating&&revealedCarrots.length===2&&col===4)effect(29);
   }
   await Promise.all(feeds);await wait(80);
   const carrotIndices=()=>board.flatMap((c,i)=>c.symbol==='CARROT'?[i]:[]);
   for(const step of plan.steps){board=structuredClone(step.board);render();
    if(step.award){const state={balance,free,freeTotal};const fresh=applyBonus(state,record);applyState(state);if(fresh){if(auto?.onFeature){auto=null;effect(43,{stopped:true})}save();effect(34,{target:$('#freePill')})}update();if(!record.featureAcknowledged){effect(31,{indices:carrotIndices()});await wait(500);await feature(step.award,plan.isFree);record.featureAcknowledged=true;save();effect(33)}}
    const result=step.result;if(!result.total){setMultiplier(0,plan.isFree);if(!plan.total){msg('本局沒有中獎。');effect(6)}break}
    const winning=result.positions,angel=winning.filter(i=>board[i].symbol==='ANGEL'),wild=winning.filter(i=>['ANGEL','DEVIL'].includes(board[i].symbol)),gold=winning.filter(i=>board[i].gold&&!['ANGEL','DEVIL'].includes(board[i].symbol));
    setMultiplier(step.index,plan.isFree);if(step.index)effect(11,{target:$('#multipliers .active')});
    lastWin=Math.round((lastWin+result.total)*100)/100;msg(`連鎖 ${step.index+1} · ×${step.multiplier}`);$$('#board .cell').forEach((n,i)=>n.classList.toggle('dim',!winning.includes(i)));effect(7,{indices:winning});if(gold.length)effect(14,{indices:gold});if(angel.length)effect(18,{indices:angel});effect(8,{indices:winning,amount:result.total});update();await wait(Math.max(850,effects.durationFor(8)));
    const next=step.next;if(wild.length)effect(23,{indices:wild});effect(9,{indices:next.replacements.map(c=>c.index)});if(next.conversions.length)effect(15,{indices:next.conversions.map(c=>c.index)});await wait(260);
    const intermediate=structuredClone(next.board);for(const copy of next.copies)intermediate[copy.index]=structuredClone(board[copy.index]);board=intermediate;render();const refill=next.replacements.length?effect(10,{indices:next.replacements.map(c=>c.index)}):null;
    const landedCarrots=next.replacements.filter(c=>board[c.index].symbol==='CARROT').map(c=>c.index);if(landedCarrots.length){effect(25,{indices:landedCarrots});if(board.filter(c=>c.symbol==='CARROT').length>=3)effect(30,{indices:landedCarrots})}
    for(const conversion of next.conversions)effect(conversion.card.symbol==='ANGEL'?16:19,{indices:[conversion.index]});await Promise.all([wait(next.conversions.length?650:280),refill?.finished]);
    if(next.copies.length){const sources=[...new Set(next.copies.map(c=>c.source))];effect(20,{indices:sources});await wait(280);effect(21,{indices:next.copies.map(c=>c.index)});effect(22,{copies:next.copies});await wait(650);board=structuredClone(next.board);render();effect(19,{indices:next.copies.map(c=>c.index)});await wait(400)}
    effect(24);await wait(150);
   }
   board=structuredClone(plan.finalBoard);const before=balance,state={balance,free,freeTotal};if(!record.demo)settleRound(state,record);else record.credited=true;applyState(state);lastWin=plan.total;save();render();effect(41,{from:before,to:balance,target:$('#balance')});
  }else{board=structuredClone(plan.finalBoard);lastWin=plan.total;render()}
  // Per-cascade amounts remain; the round total is shown once in the HUD.
  if(plan.total>=roundBet*10&&!record.rewardAcknowledged){await prize(plan.total>=roundBet*30?'MEGA WIN':'BIG WIN',plan.total,'rewardGo',plan.total>=roundBet*30?39:38);record.rewardAcknowledged=true;save()}
  if(plan.isFree&&free===0&&!record.totalAcknowledged){await prize('TOTAL WIN',freeTotal,'totalGo',36);record.totalAcknowledged=true;freeTotal=0;save();effect(33)}
  if(auto&&!plan.isFree&&!record.autoApplied){auto.left--;record.autoApplied=true;effect(43,{target:$('#auto')});if(auto.left<=0||plan.total/roundBet>=auto.ratio||balance<auto.lower||balance>auto.upper||roundBet>maxBet(balance)){auto=null;effect(43,{stopped:true})}}
  activeRound=null;msg(plan.total?`本局獲得 ${fmt(plan.total)} 蘿蔔`:'本局沒有中獎。');save();effect(12);
 }catch(error){console.error(error);auto=null;msg('牌局已保存，重新整理後繼續。');toast('已保留本局結果，請重新整理恢復。')}
 finally{busy=false;isDemo=false;render();if(plan.isFree&&free===0&&!activeRound){setMultiplier(0,false);effect(33)}idle()}
 if(activeRound)return;
 if(free>0){if(free===1){effect(35,{target:$('#freePill')});msg('最後一次免費遊戲')}await wait(400);spin()}else if(auto&&!stopRequested){await wait(650);if(auto&&!busy)spin()}
}
async function spin({demo=false}={}){if(busy||activeRound)return;if(!free&&(bet<BET_UNIT||bet>maxBet(balance))){effect(45);toast('每次下注最多為現有蘿蔔的10%');return}const isFree=free>0,plan=buildRoundPlan(engine,{bet,isFree});const record={id:crypto.randomUUID(),plan,credited:false,bonusApplied:false,demo};if(!demo){if(isFree)free--;else balance=Math.round((balance-bet)*100)/100;activeRound=record;save()}update();if(isFree)effect(34,{target:$('#freePill')});return runRecord(record)}
$('#spin').onclick=()=>spin();$('#speed').onclick=()=>{speed=(speed+1)%2;update();effect(44,{target:$('#speed')});toast(['正常速度','2× 快速模式'][speed])};
function adjust(d){if(busy||free||activeRound)return;const next=clampBet(bet+d*betStep(balance),balance);if(d>0&&next===bet){effect(45);toast(`最高下注 ${fmt(maxBet(balance))} 蘿蔔（餘額10%）`)}bet=next;update();save()}
for(const[id,d]of[['minus',-1],['plus',1]]){const button=$('#'+id);let timer,repeated=false;const stop=()=>clearTimeout(timer);button.onpointerdown=e=>{if(e.button!==0||button.disabled)return;repeated=false;button.setPointerCapture(e.pointerId);timer=setTimeout(function repeat(){repeated=true;adjust(d);timer=setTimeout(repeat,120)},400)};button.onpointerup=stop;button.onpointercancel=()=>{stop();repeated=false};button.onlostpointercapture=stop;button.onclick=()=>{stop();if(repeated){repeated=false;return}adjust(d)}}
$('#sound').onclick=()=>{soundOn=!soundOn;update();tone()};
function showExact(label,value){openModal(`<h2>${label}</h2><p class="exact-amount">${exactMoney(value)} 蘿蔔</p><div class="btn-row"><button class="btn primary" id="amountDone">明白</button></div>`);$('#amountDone').onclick=close}
$('#balanceEntry').onclick=()=>showExact('蘿蔔餘額',balance);$('#winEntry').onclick=()=>showExact('本局獎勵',lastWin);$('#sessionTotal').onclick=()=>showExact('本次淨輸贏',sessionTotal.net(balance));
$('#betEntry').onclick=()=>{if(busy||free||activeRound)return;openModal(`<h2>每次下注</h2><p>每次加減 ${fmt(betStep(balance))}（依餘額0.1%，按0.2取整）<br>最高 ${fmt(maxBet(balance))}（餘額 10%）</p><div class="chips bet-ratios">${ratioBets(balance).map(({ratio,value})=>`<button data-bet="${value}"><b>${Number((ratio*100).toFixed(1))}%</b><small>${fmt(value)}</small></button>`).join('')}</div><label class="exact-bet-label" for="exactBet">精確下注 · 0.2為單位，可輸入111M</label><input id="exactBet" inputmode="decimal" type="text" value="${bet}" autocomplete="off"><p id="betError" role="status"></p><div class="btn-row"><button class="btn" id="betCancel">取消</button><button class="btn primary" id="betDone">確認下注</button></div>`);$$('[data-bet]').forEach(b=>b.onclick=()=>{$('#exactBet').value=b.dataset.bet;$$('[data-bet]').forEach(n=>n.classList.toggle('selected',n===b));$('#betError').textContent=''});$('#betCancel').onclick=close;$('#betDone').onclick=()=>{const value=parseMoney($('#exactBet').value);if(!validBet(value)||value>maxBet(balance)){$('#betError').textContent=`請以 ${BET_UNIT} 為單位，範圍 ${BET_UNIT} 至 ${exactMoney(maxBet(balance))}`;return}bet=value;update();save();close()}};
$('#auto').onclick=()=>{if(auto){auto=null;stopRequested=true;update();effect(43,{stopped:true});return}if(busy||free||activeRound){toast('請等待本局結束');return}openModal(`<h2>Auto Play</h2><p>自動旋轉設定</p><div class="chips">${[10,20,30,40,50].map(n=>`<button data-spins="${n}" class="${n===10?'selected':''}">${n}</button>`).join('')}</div><div class="form-row"><span>旋轉次數</span><input id="autoCount" type="number" value="10" min="1" max="500"></div><div class="form-row"><label><input id="ratioOn" type="checkbox">單局獎勵達下注倍數</label><input id="ratioVal" type="number" value="100" min="1"></div><div class="form-row"><label><input id="lowerOn" type="checkbox">餘額低於</label><input id="lowerVal" type="number" value="${Math.floor(balance*.5)}" min="0"></div><div class="form-row"><label><input id="upperOn" type="checkbox">餘額高於</label><input id="upperVal" type="number" value="${Math.ceil(balance*1.5)}" min="0"></div><div class="form-row"><label><input id="featureOn" type="checkbox" checked>觸發免費遊戲後停止付費旋轉</label></div><div class="modal-note">下注最多為餘額10%；於本局結束後停止。</div><div class="btn-row"><button class="btn" id="autoCancel">取消</button><button class="btn primary" id="autoStart">開始</button></div>`,42);$('#modal').classList.add('auto-modal');$$('[data-spins]').forEach(b=>b.onclick=()=>{$('#autoCount').value=b.dataset.spins;$$('[data-spins]').forEach(n=>n.classList.toggle('selected',n===b))});$('#autoCancel').onclick=()=>close();$('#autoStart').onclick=async()=>{const count=Number($('#autoCount').value),num=s=>Number($(s).value);if(!Number.isInteger(count)||count<1||count>500||['#ratioVal','#lowerVal','#upperVal'].some(s=>!Number.isFinite(num(s))||num(s)<0)){toast('請輸入有效設定');return}auto={left:count,ratio:$('#ratioOn').checked?num('#ratioVal'):Infinity,lower:$('#lowerOn').checked?num('#lowerVal'):-Infinity,upper:$('#upperOn').checked?num('#upperVal'):Infinity,onFeature:$('#featureOn').checked};if(auto.lower>=auto.upper){auto=null;toast('下限須低於上限');return}effect(43);await close();spin()}};
const rules=`<p class="modal-note">模型版本：${MATH_VERSION}。已開始的牌局保留原結果，新模型從下一局生效。</p><h3>怎樣中獎？</h3><p>盤面為 5 列 × 4 行，共 1024 ways。相同符號由最左列開始，連續出現在至少 3 列即可中獎，不需要同一行。各列可用位置數相乘，就是中獎 ways。</p><h3>金牌及 WILD</h3><p>金牌只會出現在第 2–4 列。金牌參與中獎後轉成天使或惡魔 WILD。WILD 可替代普通符號，不能替代 CARROT。惡魔會將第 2–5 列的 1–4 個合資格普通牌位轉為惡魔 WILD；不取代 CARROT 或已有 WILD。</p><h3>消除與倍率</h3><p>中獎普通牌消除，新牌由上方落入原空位。未中獎牌留在原位。普通遊戲倍率依序 ×1、×2、×3、×5；下一次付費旋轉重置。</p><h3>CARROT 與免費遊戲</h3><p>同一盤面有 3 個或以上 CARROT，獲得 10 次免費遊戲；免費遊戲中再出現 3 個或以上，加 5 次。免費倍率為 ×2、×4、×6、×10。同一次旋轉只發放一次 CARROT 獎勵，避免保留符號重複觸發。</p><h3>蘿蔔與下注</h3><p>每次付費下注最多為當時餘額的 10%。免費遊戲沿用觸發局下注額，不扣蘿蔔。Auto 每次開始前重新檢查上限。加減依目前餘額的0.1%換算、按0.2取整，長按可連續調整；BET 可快選比例或輸入精確金額。</p><p>100 萬起以 M／B／T 顯示，小數固定三位。點擊餘額、本局獎勵或右上本次淨輸贏可查看完整金額。本次淨輸贏以此分頁開啟時的餘額為基準，重新整理後保留。</p><p class="modal-note">私人試玩版：測試蘿蔔只保存在此瀏覽器，不能充值、兌現或轉移。目前採自訂固定列權重模型，非 JILI 原版概率。參考模擬：固定下注20、100萬次付費局並計入免費回合，RTP估計96.55%，95%信賴區間約95.55%–97.56%；不是已認證理論值。下注以0.2為單位，避免極小下注逐筆四捨五入失真。</p>`;
function help(tab='rules'){openModal(`<h2>玩法與計算</h2><div class="tabs"><button id="rulesTab" class="${tab==='rules'?'active':''}">玩法</button><button id="payTab" class="${tab==='pay'?'active':''}">賠付與例子</button></div>${tab==='rules'?rules:`<p class="modal-note">以下為此自訂模型的賠付表，以本版本總下注額計算；不是 JILI 官方概率或賠付保證。</p><table><thead><tr><th>符號</th><th>3列</th><th>4列</th><th>5列</th></tr></thead><tbody>${Object.entries(DEFAULT_PAYTABLE).map(([s,v])=>`<tr><td>${suits[s]||s}</td>${v.map(n=>`<td>×${n}</td>`).join('')}</tr>`).join('')}</tbody></table><h3>計算方法</h3><p>同符號獎勵＝賠付值 × 中獎 ways × 下注額 × 當前倍率。多種符號中獎分別計算再相加，金額以兩位小數記錄。</p><p>例：下注 20、A 連續 3 列各有 1、2、1 個可用位置，ways＝1×2×1＝2。當前倍率 ×2，獎勵＝0.5×2×20×2＝40 蘿蔔。</p><p>參考：<a href="https://jiligames.com/PlusIntro/49?showGame=false" target="_blank" rel="noopener">JILI 原版介紹</a>。</p>`}<div class="btn-row"><button class="btn" id="replayTutorial">重看教學</button><button class="btn primary" id="helpDone">明白</button></div>`);$('#rulesTab').onclick=()=>help('rules');$('#payTab').onclick=()=>help('pay');$('#helpDone').onclick=close;$('#replayTutorial').onclick=()=>tutorial(0)}
$('#help').onclick=()=>help();$('#settings').onclick=()=>{openModal(`<h2>你的遊戲節奏</h2><p>隨時調整速度，派牌結果不會因此改變。</p><div class="chips">${['正常','快速'].map((s,i)=>`<button data-speed="${i}" class="${i===speed?'selected':''}">${s}</button>`).join('')}</div><div class="form-row"><label><input type="checkbox" id="soundCheck" ${soundOn?'checked':''}>遊戲音效</label></div><p class="modal-note">下注最多為蘿蔔餘額的10%。試玩餘額保存在此瀏覽器。</p><div class="btn-row"><button class="btn" id="resetTestBalance">重設蘿蔔</button><button class="btn primary" id="settingsDone">完成</button></div>`);$$('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);effect(44,{target:b});$$('[data-speed]').forEach(n=>n.classList.toggle('selected',n===b));update()});$('#soundCheck').onchange=e=>{soundOn=e.target.checked;update();tone()};$('#settingsDone').onclick=close;$('#resetTestBalance').onclick=resetPlaytest};
const lessons=[['不同位置，也能連成幸運','由最左列開始，至少連續 3 列出現同一符號即可中獎，不必在同一行。','<div class="tutorial-cards"><img src="assets/art/card-normal-H.png" alt="紅心"><img style="margin-top:15px" src="assets/art/card-normal-H.png" alt="紅心"><img style="margin-top:30px" src="assets/art/card-normal-H.png" alt="紅心"></div>'],['金牌翻面，WILD 登場','金牌中獎後轉成天使或惡魔。天使替代普通牌，惡魔還可擴散到其他合資格牌位。','<div class="feature-carrots"><img src="assets/art/wild-angel.png" alt="天使小WILD"><img src="assets/art/wild-devil.png" alt="惡魔大WILD"></div>'],['三個 CARROT，金色時刻','同一盤面出現至少 3 個 CARROT，即可進入 10 次免費遊戲。免費遊戲內可追加次數。','<div class="feature-carrots">'+[1,2,3].map(()=>'<img src="assets/art/carrot-bonus.png" alt="CARROT">').join('')+'</div>'],['選好節奏，開始你的 Gala','下注不超過蘿蔔餘額 10%。AUTO 可設定停止條件；SPEED 可在正常、2× 快速間切換。教學不扣蘿蔔。','<div class="tutorial-cards"><img src="assets/carrot.png" alt="下注最多餘額10%"><img src="assets/art/ui/buttons/auto/normal.svg" alt="AUTO"><img src="assets/art/ui/buttons/speed-normal/normal.svg" alt="SPEED"></div>']];
function tutorial(i){const [title,text,art]=lessons[i];openModal(`<h2>${title}</h2>${art}<p>${text}</p><div class="tutorial-progress">${lessons.map((_,j)=>`<i class="${j===i?'active':''}"></i>`).join('')}</div><div class="btn-row"><button class="btn" id="skipLesson">跳過</button><button class="btn primary" id="nextLesson">${i===3?'開始遊戲':'下一步'}</button></div>`,47);const done=()=>{localStorage.setItem('gala-carrot-tutorial','1');close()};$('#skipLesson').onclick=done;$('#nextLesson').onclick=()=>i===3?done():tutorial(i+1)}
const resetPlaytest=()=>{if(busy||free||activeRound){toast('請先完成目前遊戲');return}openModal('<h2>重新開始試玩？</h2><p>將本瀏覽器的測試蘿蔔重設為 2,000，並停止 Auto。</p><div class="btn-row"><button class="btn" id="cancelReset">取消</button><button class="btn primary" id="confirmReset">重設</button></div>');$('#cancelReset').onclick=close;$('#confirmReset').onclick=()=>{auto=null;balance=2000;bet=20;lastWin=0;sessionTotal.reset(balance);save();render();close();msg('新的金色時刻，開始吧。')}};
const demoAnimation=()=>{if(busy||free||activeRound){toast('請先完成目前遊戲');return}auto=null;spin({demo:true})};
$('.mouths').innerHTML=Array.from({length:5},()=>'<div class="mouth"><img class="dealer-outlet-art" src="assets/art/v4/dealer-outlet.svg" alt=""><div class="dealer-ready-window"><img src="assets/back.png" alt=""></div><div class="dealer-front-lip"><img src="assets/art/v4/dealer-outlet.svg" alt=""></div></div>').join('');
function alignDealer(){$('.game').style.setProperty('--board-width',$('.board-shell').getBoundingClientRect().width+'px');scenes.resize()}
new ResizeObserver(alignDealer).observe($('.board-shell'));window.addEventListener('resize',()=>{fitAmounts();alignDealer()});document.fonts.ready.then(fitAmounts);
function pausePresentation(reason){if(pauseReasons.has(reason))return;pauseReasons.add(reason);effect(48,{target:$('.game')});playback.pause();effects.pause();document.documentElement.dataset.playbackPaused='true';save();if(reason==='offline'&&!$('#connectionDialog').open)$('#connectionDialog').showModal()}
function resumePresentation(reason){pauseReasons.delete(reason);if(reason==='offline')$('#connectionDialog').close();if(pauseReasons.size)return;delete document.documentElement.dataset.playbackPaused;playback.resume();effects.resume();effect(48,{resuming:true,target:$('.game')})}
document.addEventListener('visibilitychange',()=>document.hidden?pausePresentation('hidden'):resumePresentation('hidden'));
window.addEventListener('offline',()=>pausePresentation('offline'));window.addEventListener('online',()=>resumePresentation('offline'));window.addEventListener('pagehide',()=>save());
$('#connectionDialog').addEventListener('cancel',e=>e.preventDefault());if(!navigator.onLine)pausePresentation('offline');if(document.hidden)pausePresentation('hidden');
async function resumeRecovery(){recoveryPrompt=false;$('#modal').close();if(activeRound)return runRecord(activeRound,{recovering:true});if(free)return spin()}
render();setMultiplier(0,free>0||!!activeRound?.plan.isFree);alignDealer();idle();
if(activeRound||free){recoveryPrompt=true;openModal('<h2>繼續已保存的牌局</h2><p>本局結果已保留，恢復不會重新扣除下注或重複發放獎勵。</p><div class="btn-row"><button class="btn primary" id="resumeRound">繼續牌局</button></div>',48);$('#resumeRound').onclick=resumeRecovery}else if(!reviewMode&&!localStorage.getItem('gala-carrot-tutorial'))setTimeout(()=>tutorial(0),700);
window.galaDebug={getState:()=>({mathVersion:MATH_VERSION,scene:scenes.state,balance,bet,sessionNet:sessionTotal.net(balance),board:structuredClone(board),free,busy,speed,auto,activeRound:activeRound?{id:activeRound.id,credited:activeRound.credited,bonusApplied:activeRound.bonusApplied,mathVersion:activeRound.plan.mathVersion??'legacy-unversioned'}:null}),spin,help,tutorial,demoAnimation,resetPlaytest,effects,scenes,previewFeature:(n=10,extra=false)=>feature(n,extra),definitions:ANIMATION_DEFINITIONS,previewAnimation:id=>effects.preview(id),setReviewState:state=>{if(!reviewMode)return;if(Number.isFinite(state.balance))balance=state.balance;if(Number.isFinite(state.bet))bet=state.bet;if(Number.isFinite(state.lastWin))lastWin=state.lastWin;if(state.board)board=structuredClone(state.board);if(Number.isInteger(state.heat))setMultiplier(state.heat,!!state.isFree);render()},setReviewSpeed:mode=>{if(reviewMode){speed=Number(mode)===1?1:0;update()}},previewReward:(amount=280)=>prize(amount>=600?'MEGA WIN':'BIG WIN',amount,'rewardGo',amount>=600?39:38),pause:()=>pausePresentation('review'),resume:()=>resumePresentation('review')};
